using AcxiomCrm.Data;using AcxiomCrm.Models;using AcxiomCrm.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System.Security.Claims;
namespace AcxiomCrm.Controllers;
[Authorize]public class OpportunitiesController:Controller{private readonly ApplicationDbContext _db;private readonly AuditService _audit;public OpportunitiesController(ApplicationDbContext db,AuditService audit){_db=db;_audit=audit;}
public async Task<IActionResult>Index(string? search){var q=_db.Opportunities.AsNoTracking().AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var id=User.FindFirstValue(ClaimTypes.NameIdentifier);q=q.Where(x=>x.AssignedTo==id);}if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.OpportunityName.Contains(search)||x.Stage.Contains(search)||x.Status.Contains(search));ViewData["Search"] = search;return View(await q.OrderByDescending(x=>x.CreatedDate).ToListAsync());}
public async Task<IActionResult>Create(){ViewData["Customers"] = await _db.Customers.OrderBy(x=>x.CustomerName).ToListAsync();return View(new Opportunity());}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Opportunity x){if(x.Amount<=0)ModelState.AddModelError(nameof(x.Amount),"Opportunity Amount must be greater than 0.");if(x.Probability<0||x.Probability>100)ModelState.AddModelError(nameof(x.Probability),"Probability must be between 0 and 100.");if(x.Status=="Open"&&x.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(x.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(!ModelState.IsValid){ViewData["Customers"] = await _db.Customers.OrderBy(z=>z.CustomerName).ToListAsync();return View(x);}x.AssignedTo=User.FindFirstValue(ClaimTypes.NameIdentifier);_db.Add(x);await _db.SaveChangesAsync();await _audit.LogAsync("Create","Opportunity",x.OpportunityId.ToString(),newValue:x);return RedirectToAction(nameof(Index));}
public async Task<IActionResult>Edit(int id){var x=await _db.Opportunities.FindAsync(id);if(x==null)return NotFound();ViewData["Customers"] = await _db.Customers.ToListAsync();return View(x);}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,Opportunity x){if(id!=x.OpportunityId)return BadRequest();if(x.Amount<=0)ModelState.AddModelError(nameof(x.Amount),"Opportunity Amount must be greater than 0.");if(x.Probability<0||x.Probability>100)ModelState.AddModelError(nameof(x.Probability),"Probability must be between 0 and 100.");if(x.Status=="Open"&&x.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(x.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(!ModelState.IsValid){ViewData["Customers"] = await _db.Customers.ToListAsync();return View(x);}var old=await _db.Opportunities.AsNoTracking().FirstOrDefaultAsync(z=>z.OpportunityId==id);_db.Update(x);await _db.SaveChangesAsync();await _audit.LogAsync("Update","Opportunity",id.ToString(),old,x);return RedirectToAction(nameof(Index));}
[Authorize(Roles="Admin,Manager")]public async Task<IActionResult>Delete(int id){var x=await _db.Opportunities.FindAsync(id);return x==null?NotFound():View(x);}
[HttpPost,Authorize(Roles="Admin,Manager"),ValidateAntiForgeryToken,ActionName("Delete")]public async Task<IActionResult>DeleteConfirmed(int id){var x=await _db.Opportunities.FindAsync(id);if(x!=null){_db.Remove(x);await _db.SaveChangesAsync();await _audit.LogAsync("Delete","Opportunity",id.ToString(),oldValue:x);}return RedirectToAction(nameof(Index));}}
